// Runtime configuration for Unity Catalog UI.
// In production, this file is generated by docker-entrypoint.sh from environment variables.
// For local development, edit this file directly.
window.__UC_CONFIG__ = {
  // Backend API base URL. Empty string means same-origin (proxied by Vite in dev, nginx in prod).
  apiUrl: "",
  // Set to true to enable OIDC authentication.
  authEnabled: false,
  // OIDC provider discovery URL (e.g., "https://forgejo.example.com").
  // Must support OpenID Connect Discovery (/.well-known/openid-configuration).
  oidcAuthority: "",
  // OIDC client ID registered with your provider.
  oidcClientId: "",
  // Space-separated OIDC scopes.
  oidcScopes: "openid profile email",
};
